  String? get VERSION => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 4);
  ///  Identifier of the emission profile the card conforms to, verbatim, naming
  ///  the annex revision the publisher implemented.
  String? get PROFILE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 6);
  ///  Line terminator the card text uses.
  vcfLineEnding get LINE_ENDING => vcfLineEnding.fromValue(const fb.Int8Reader().vTableGet(_bc, _bcOffset, 8, 0));
  vcfLineEnding get lineEnding => LINE_ENDING;
