  ///  means the card is a valid record that is NOT servable on that surface.
  bool get WITHIN_BYTE_BUDGET => const fb.BoolReader().vTableGet(_bc, _bcOffset, 18, false);
  bool get withinByteBudget => WITHIN_BYTE_BUDGET;
