  ///  Empty under every other policy.
  String? get PHOTO_URI => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 20);
  String? get photoUri => PHOTO_URI;
  ///  Media type of the portrait content verbatim, when one is carried.
