  String? get PRODUCER_VERSION => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 28);
  String? get producerVersion => PRODUCER_VERSION;
  ///  RFC 3339 UTC fixed-millisecond timestamp at which the card was projected.
